<section class="relatorio-hero"><div><h2>Alunos e situação da DVA</h2><p>Consulta de DVAs correntes. Cada aluno aparece uma vez.</p></div>
<div class="relatorio-hero-stats"><div class="relatorio-stat"><strong><?= (int)$result['total'] ?></strong><span>Alunos no filtro</span></div><div class="relatorio-stat"><strong><?= (int)$result['pages'] ?></strong><span>Páginas da prévia</span></div><div class="relatorio-stat"><strong><?= (int)$result['page'] ?></strong><span>Página atual</span></div></div></section>
<section class="relatorio"><h3>Filtros da consulta</h3>
<form method="get" action="<?= e(url('relatorio')) ?>" class="row g-3 mb-3"><div class="col-md-4"><label for="turma">Turma</label><select class="form-select" id="turma" name="turma"><option value="">Todas</option><?php foreach ($classes as $class): ?><option value="<?= (int)$class['id'] ?>" <?= (string)$result['filters']['turma']===(string)$class['id'] ? 'selected' : '' ?>><?= e($class['nome_turma']) ?></option><?php endforeach; ?></select></div><div class="col-md-4"><label for="dva">Situação da DVA</label><select class="form-select" id="dva" name="dva"><option value="">Todas</option><?php foreach (DvaStatus::ALL as $status): ?><option value="<?= e($status) ?>" <?= $result['filters']['dva']===$status ? 'selected' : '' ?>><?= e(DvaStatus::label($status)) ?></option><?php endforeach; ?></select></div><div class="col-md-4"><label for="ativo">Situação do aluno</label><select class="form-select" id="ativo" name="ativo"><option value="1" <?= $result['filters']['ativo']==='1' ? 'selected' : '' ?>>Ativos</option><option value="0" <?= $result['filters']['ativo']==='0' ? 'selected' : '' ?>>Inativos</option><option value="todos" <?= $result['filters']['ativo']==='todos' ? 'selected' : '' ?>>Todos</option></select></div><div class="col-12"><button class="btn btn-primary">Filtrar</button></div></form>
<?php $params=http_build_query($result['filters']); ?><p><?= (int)$result['total'] ?> resultado(s) no filtro. Exportações incluem todas as páginas e refletem o momento da geração.</p><p>PDF: até 500 alunos. CSV: até 10.000 alunos. Para resultados maiores, escolha uma turma ou refine a situação.</p><p><a class="btn btn-primary" href="<?= e(url('relatorio/pdf?'.$params)) ?>">Gerar PDF</a> <a class="btn btn-outline-primary" href="<?= e(url('relatorio/csv?'.$params)) ?>">Baixar CSV</a> <button class="btn btn-outline-secondary" type="button" data-print-page>Imprimir prévia</button></p>
<div class="table-scroll"><table class="table"><thead><tr><th>Aluno</th><th>Turma</th><th>Nascimento</th><th>Vencimento DVA</th><th>Situação DVA</th><th>Situação aluno</th></tr></thead><tbody><?php foreach ($result['items'] as $row): ?><tr><td><?= e($row['nome_completo']) ?></td><td><?= e($row['nome_turma'] ?? 'Sem turma') ?></td><td><?= e(RelatorioAlunos::displayDate($row['data_nascimento'])) ?></td><td><?= e(RelatorioAlunos::displayDate($row['data_vencimento'])) ?></td><td><?= e(DvaStatus::label($row['dva_status'])) ?></td><td><?= $row['ativo'] ? 'Ativo' : 'Inativo' ?></td></tr><?php endforeach; ?></tbody></table></div>
<?php if ($result['items']===[]): ?><p>Nenhum aluno encontrado para os filtros.</p><?php endif; ?>
<nav aria-label="Páginas"><?php for ($p=1;$p<=$result['pages'];$p++): ?><a class="btn btn-sm <?= $p===$result['page'] ? 'btn-primary' : 'btn-outline-primary' ?>" href="<?= e(url('relatorio?'.$params.'&pagina='.$p)) ?>"><?= $p ?></a> <?php endfor; ?></nav></section>
